package screenplay

import (
	"compress/gzip"
	"encoding/json"
	"os"
	"reflect"
	"testing"
)

// These are outputs of the installed original compiled evaluator, captured with
// invented input and networking denied. They are not expectations generated by CM.
func TestStoryboardPlanCoverageOriginalGolden(t *testing.T) {
	f, err := os.Open("testdata/storyboard_plan_coverage_original.json.gz")
	if err != nil {
		t.Fatal(err)
	}
	defer f.Close()
	z, err := gzip.NewReader(f)
	if err != nil {
		t.Fatal(err)
	}
	defer z.Close()
	var fixture struct {
		Cases []struct {
			Label, Input, Density string
			Output                StoryboardPlanCoverage
		}
	}
	if err = json.NewDecoder(z).Decode(&fixture); err != nil {
		t.Fatal(err)
	}
	for _, row := range fixture.Cases {
		t.Run(row.Label+"/"+row.Density, func(t *testing.T) {
			actual := EvaluateStoryboardPlan(row.Input, row.Density)
			if !reflect.DeepEqual(actual, row.Output) {
				t.Errorf("original=%+v\nCM=%+v", row.Output, actual)
			}
		})
	}
}
